              hydration_hooks=None, **handlers):
    # Validate inputs
    if mode not in ("READ", "WRITE"):
        raise ValueError("Only 'READ' and 'WRITE' access mode supported")
    if bookmarks:
        if not isinstance(bookmarks, (list, tuple)):
            raise TypeError("'bookmarks' should be a list or tuple of strings")
        for bookmark in bookmarks:
            if not isinstance(bookmark, str):
                raise TypeError("'bookmarks' should be a list or tuple of strings")
    if metadata:
        if not isinstance(metadata, dict):
            raise TypeError("'metadata' should be a dict")
    if timeout:
        if not isinstance(timeout, (int, float)):
            raise TypeError("'timeout' should be a positive number")
        if timeout <= 0:
            raise ValueError("'timeout' should be a positive number")
    if db:
        if not isinstance(db, str):
            raise TypeError("'db' should be a string")
    if imp_user:
        if not isinstance(imp_user, (list, tuple)):
            raise TypeError("'imp_user' should be a list or tuple of values")
        for user in imp_user:
            if not isinstance(user, str):
                raise TypeError("'imp_user' should be a list or tuple of strings")
    if dehydration_hooks:
        if not isinstance(dehydration_hooks, dict):
            raise TypeError("'dehydration_hooks' should be a dict")
        for key, value in dehydration_hooks.items():
            if not callable(value):
                raise TypeError("'dehydration_hooks' should be a dict of callables")
    if hydration_hooks:
        if not isinstance(hydration_hooks, dict):
            raise TypeError("'hydration_hooks' should be a dict")
        for key, value in hydration_hooks.items():
            if not callable(value):
                raise TypeError("'hydration_hooks' should be a dict of callables")

    # Get current time
    metadata_ts = datetime.now().timestamp()

    # Build transaction metadata
    metadata = {
        "access_mode": mode,
        "bookmarks": bookmarks,
        "metadata": metadata,
        "timeout": timeout,
        "db": db,
        "imp_user": imp_user,
        "dehydration_hooks": dehydration_hooks,
        "hydration_hooks": hydration_hooks,
        "handlers": handlers,
    }

    # Initialize default dehydration and hydration hooks if none provided
    if not dehydration_hooks:
        dehydration_hooks = {
            str: packstream_transforms.dehydrate_string,
            int: packstream_transforms.dehydrate_integer,
            float: packstream_transforms.dehydrate_float,
            bool: packstream_transforms.dehydrate_boolean,
            None: packstream_transforms.dehydrate_null,
        }
    if not hydration_hooks:
        hydration_hooks = {
            str: packstream_transforms.hydrate_string,
            int: packstream_transforms.hydrate_integer,
            float: packstream_transforms.hydrate_float,
            bool: packstream_transforms.hydrate_boolean,
            None: packstream_transforms.hydrate_null,
        }

    # Generate BEGIN message
    message = Message(
        metadata=packstream_transforms.METADATA_BEGIN,
        value=packstream_transforms.serialize_transaction_metadata(metadata),
        ts=metadata_ts,
    )

    # Add message to queue
    self._queue_message(message)

    # Return Response object
    if not self._is_stream:
        response = Response(
            ts=metadata_ts, response_id=packstream_transforms.RESPONSE_ID_DEF,
            stream=None
        )
    else:
        response = Response(
            ts=metadata_ts, response_id=packstream_transforms.RESPONSE_ID_STREAM,
            stream=self
        )
    return response

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None, db=None, imp_user=None, dehydration_hooks=None, hydration_hooks=None, **handlers):
    body = pack.pack({
        "mode": mode,
        "bookmarks": list(bookmarks) if bookmarks else [],
        "metadata": metadata,
        "timeout": timeout,
        "db": db,
        "imp_user": imp_user,
        "dehydration_hooks": dehydration_hooks,
        "hydration_hooks": hydration_hooks,
        "handlers": handlers
    })
    return Response(self, MSG_BEGIN, body)

