        return (self.x - other.x) == 0 and (self.y - other.y) == 0

    def __ne__(self, other):
        return (self.x - other.x) != 0 or (self.y - other.y) != 0

    def distance(self, other):
        return math.sqrt((self.x - other.x) ** 2 + (self.y - other.y) ** 2)

