def cached(cache, key=hashkey, lock=None):
  def decorator(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
      if cache.get(key(*args, **kwargs)):
        return cache.get(key(*args, **kwargs))
      else:
        result = func(*args, **kwargs)
        if lock:
          lock.acquire()
          cache[key(*args, **kwargs)] = result
