def format(sql, params):
	import re
	import collections

	if not isinstance(sql, (str, bytes)):
		raise TypeError("sql must be str or bytes")
	if not isinstance(params, (collections.abc.Mapping, collections.abc.Sequence)):
		raise TypeError("params must be Mapping or Sequence")
	if isinstance(params, collections.abc.Mapping):
		params = list(params.items())
	elif isinstance(params, collections.abc.Sequence):
		params = list(params)
	else:
		raise TypeError("params must be Mapping or Sequence")
	for param in params:
		if not isinstance(param, (collections.abc.Mapping, collections.abc.Sequence)):
			raise TypeError("each parameter must be Mapping or Sequence")
		if not param:
			continue
		key, value = param.popitem()
		if not isinstance(key, (str, int)):
			raise TypeError("each key must be str or int")
		if not isinstance(value, (str, bytes)):
			raise TypeError("each value must be str or bytes")

	param_index = 0
	param_mapping = {}
	for param in params:
		param_key = f"param{param_index}"
		param_index += 1
		param_mapping[param_key] = param

	pattern = r"\:([a-zA-Z_]+)"
	sql = re.sub(pattern, lambda m: param_mapping[m.group(1)], sql)
	return sql, param_mapping

