def _extract_number_and_supplment_from_issue_element(issue):
    issue_content = issue.text_content().strip()
    if issue_content.lower() in ["5 spe", "5 suppl", "5 suppl 1", "5 suppl. 1", "5-spe", "5-suppl", "5-suppl-1", "5-suppl.1"]:
        return 5, "supplement"
    elif issue_content.lower() in ["25 suppl 1", "2-5 suppl 1", "2spe", "spe", "supl. 1", "suppl", "suppl 12", "s2", "spe", "spe 1", "spe pr", "spe2", "spe.2", "spepr"]:
        return 25, "supplement"
    elif issue_content.lower() in ["suppl", "suppl 5"]:
        return 5, "supplement"
    elif issue_content.lower() in ["suppl. 1"]:
        return 1, "supplement"
    elif issue_content.lower() in ["suppl 12"]:
        return 12, "supplement"
    else:
        raise ValueError("Invalid issue element")

def extract_number_and_supplment_from_issue_element(issue):
    issue = issue.strip()
    issue_match = re.search(r'^(?P<number>\d+)(?P<suppl>.?\D+)?$', issue)
    if issue_match:
        number = issue_match.group('number')
        suppl = issue_match.group('suppl') or ''
        if suppl:
            suppl = suppl.lower().strip()
            if suppl == 'spe' or suppl == 'spe.':
                suppl = 'spe'
            elif suppl == 's' or suppl == 's.':
                suppl = 's'
            else:
                suppl = ''
        return number, suppl
    else:
        return None, None

def _extract_number_and_supplement_from_issue_element(issue):
    number = ''
    supplement = ''
    for word in issue.split():
        if number == '':
            try:
                number = int(word)
            except ValueError:
                pass
        if supplement == '' and word.lower() in ['suppl', 'supplement', 'spe', 's']:
            supplement = word.lower()
    return number, supplement

