        if isinstance(expr, bool):
            result.append(expr)
        elif isinstance(expr, BinaryOp):
            name, left, right = expr
            if name == "&":
                if left.name == "&" or left.name == "|":
                    result += absorb([left.left, left.right, right])
                elif left.name == "~":
                    result += absorb([left.right, right])
            elif name == "|":
                if left.name == "&" or left.name == "|":
                    result += absorb([left.left, left.right, right])
                elif left.name == "~":
