    for arg in args:
        if arg.is_atom():
            new_args.append(arg)
        else:
            children = arg.children()
            if arg.operator() == '|':
                if children[0].is_constant() and children[1].is_constant():
                    new_args.append(arg)
                elif children[0].is_constant():
                    new_args.append(children[1])
                elif children[1].is_constant():
                    new_args.append(children[0])
                else:
                    new_args.append(arg)
            elif arg.operator() == '&':
                if children[0].is_constant() and children[1].is_constant():
                    new_args.append(arg)
                elif children[0].is_constant():
                    new_args.append(children[1])
                elif children[1].is_constant():
                    new_args.append(children[0])
                else:
                    new_args.append(arg)
            else:
                new_args.append(arg)
    return new_args

