def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError: 

    """
    netloc = ""
    use_ssl = False
    image_id = ""

    if image_href.startswith("https"):
        use_ssl = True
    else:
        use_ssl = False

    if ";" in image_href:
        image_href, netloc = image_href.split(";", 1)
        netloc = netloc.split(":", 1)[0]
    elif "@" in image_href:
        netloc = image_href.split("@")[1]
    else:
        netloc = None

    if "?" in image_href:
        image_href, path = image_href.split("?")
    else:
        path = None

    if "#" in image_href:
        image_href, image_id = image_href.split("#", 1)
    else:
        image_id = None

    return (image_id, netloc, use_ssl)

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    # urllib.parse is not available in Python 2
    # https://stackoverflow.com/questions/2673450/alternative-for-urlparse
    if sys.version_info < (3, 0):
        from urllib import splitquery
        image_id = splitquery(image_href)[1]
    else:
        from urllib.parse import urlparse
        url_parts = urlparse(image_href)
        image_id = url_parts.path[1:]

    netloc = url_parts.netloc
    use_ssl = url_parts.scheme == "https"
    return (image_id, netloc, use_ssl)

