def fromutc(self, dt):
    if not isinstance(dt, datetime):
        raise TypeError("Expected a datetime object, got {0}".format(type(dt)))
    if not zones.contains(dt.tzinfo):
        raise ValueError("Timezone not found in zoneinfo database: {0}".format(dt.tzinfo))
    new_tz = zones[self._config['timezone']]
    new_dt = dt.astimezone(new_tz)
    if new_tz.is_dst(new_dt):
        new_dt -= timedelta(seconds=new_tz.dstoffset)
    return new_dt

