        raise ValueError("'dt' must be a timezone-aware datetime")
    if dt.tzinfo != self._abbrev:
        raise ValueError("'dt' must be in timezone %s" % self._abbrev)
    new_dt = dt.astimezone(self._tz)
    if new_dt.fold:
