def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if "include_dict" in parser_dict:
        if not isinstance(parser_dict["include_dict"], dict):
            raise RuntimeError(f"Invalid include_dict in {self.__class__.__name__}: {parser_dict['include_dict']}")
        for key, value in parser_dict["include_dict"].items():
            if not isinstance(key, str):
                raise RuntimeError(f"Invalid key in include_dict: {key}")
            if not isinstance(value, str):
                raise RuntimeError(f"Invalid value in include_dict: {value}")
            try:
                target = parser_dict[value]
            except KeyError:
                raise RuntimeError(f"Target {value} not found in {self.__class__.__name__}")
            parser_dict[key] = target
    return parser_dict

def include_groups(parser_dict):
    for include_group in parser_dict.get("$include-groups", []):
        include_group_name = include_group["name"]
        include_group_number = include_group["number"]
        include_group_path = os.path.join(self.working_dir, include_group["path"])
        if include_group_name in self.groups:
            include_group = self.groups[include_group_name] 
            include_group.extend(include_group_number)
        else:
            self.groups[include_group_name] = {include_group_number}
        # check if the include group is in the default or clustered group
        if include_group_number in ["default", "clustered"]:
            self._add_include_group(include_group)
        elif include_group_number in self.clusters:
            self.clusters[include_group_number].extend(include_group)
        else:
            self.groups[include_group_number].extend(include_group) 
        # recursively call the method on the include group
        include_group.include_groups(parser_dict)

